package fable.hideseek.imba.item;import fable.hideseek.imba.ImbaExtension;import fable.hideseek.imba.config.OverlayBarrierConfig;import fable.hideseek.imba.net.OverlayBarrierNetworking;import net.fabricmc.fabric.api.event.player.UseBlockCallback;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.text.Text;import net.minecraft.util.ActionResult;public final class OverlayBarrierToolHandler{private OverlayBarrierToolHandler(){}public static void register(){UseBlockCallback.EVENT.register((player,world,hand,hit)->{if(!player.getStackInHand(hand).isOf(ImbaExtension.OVERLAY_BARRIER))return ActionResult.PASS;if(world.isClient)return ActionResult.SUCCESS;if(!(player instanceof ServerPlayerEntity serverPlayer)||!player.hasPermissionLevel(2))return ActionResult.FAIL;ServerWorld serverWorld=(ServerWorld)world;boolean removed=player.isSneaking();boolean changed=removed?OverlayBarrierConfig.remove(serverWorld,hit.getBlockPos()):OverlayBarrierConfig.add(serverWorld,hit.getBlockPos());if(changed){OverlayBarrierNetworking.broadcast(serverPlayer.getServer());player.sendMessage(Text.literal(removed?"§eНакладываемый барьер удалён":"§aНакладываемый барьер добавлен поверх блока"),true);}return ActionResult.SUCCESS;});}}
